sys_script_client.script:
function onLoad() {
    if (typeof g_form === 'undefined' || g_form.isNewRecord()) return;

    var tableName = g_form.getTableName();
    var sysId = g_form.getUniqueValue();
    if (!tableName || !sysId) return;

    var ga = new GlideAjax('PulseBoxAIAB');
    ga.addParam('sysparm_name', 'getPendingSuggestions');
    ga.addParam('sysparm_target_table', tableName);
    ga.addParam('sysparm_target_sys_id', sysId);
    ga.getXMLAnswer(function(answer) {
        try {
            var suggestions = JSON.parse(answer);
            if (suggestions && suggestions.length > 0) {
                window.g_pulseboxSuggestions = suggestions;
                window.g_pulseboxIndex = 0;
                showPulseBoxBadge(suggestions);
            }
        } catch (e) {
            console.log('PulseBox: Parse error', e);
        }
    });
}

function showPulseBoxBadge(suggestions) {
    var count = suggestions.length;

    var badge = document.createElement('div');
    badge.id = 'pulsebox-badge';
    badge.innerHTML = '<span style="font-size:16px;">🤖</span> ' + count + ' AI suggestion' + (count > 1 ? 's' : '');
    badge.style.cssText = 'position:fixed;bottom:20px;left:20px;background:#007bff;color:white;' +
        'padding:8px 16px;border-radius:20px;font-size:14px;z-index:9999;cursor:pointer;' +
        'box-shadow:0 2px 8px rgba(0,0,0,0.2);transition:all 0.2s;';

    badge.onmouseover = function() { this.style.transform = 'scale(1.05)'; };
    badge.onmouseout = function() { this.style.transform = 'scale(1)'; };
    badge.onclick = function() { showPulseBoxModal(); };

    document.body.appendChild(badge);
}

function showPulseBoxModal() {
    var suggestions = window.g_pulseboxSuggestions;
    var idx = window.g_pulseboxIndex || 0;
    if (!suggestions || suggestions.length === 0) return;

    var s = suggestions[idx];
    var total = suggestions.length;

    // Remove existing modal
    var existing = document.getElementById('pulsebox-modal-overlay');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.id = 'pulsebox-modal-overlay';
    overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:10000;display:flex;align-items:center;justify-content:center;';

    var modal = document.createElement('div');
    modal.style.cssText = 'background:white;border-radius:8px;width:600px;max-width:90%;max-height:80%;overflow:auto;box-shadow:0 4px 20px rgba(0,0,0,0.3);';

    var header = '<div style="padding:16px;border-bottom:1px solid #ddd;display:flex;justify-content:space-between;align-items:center;">' +
        '<strong>🤖 PulseBox Suggestion ' + (idx + 1) + ' of ' + total + '</strong>' +
        '<span style="cursor:pointer;font-size:20px;" onclick="closePulseBoxModal()">×</span></div>';

    var body = '<div style="padding:16px;">' +
        '<p><strong>Agent:</strong> ' + s.agent_name + '</p>' +
        '<p><strong>Field:</strong> ' + s.field_name + '</p>' +
        '<p><strong>Suggestion:</strong></p>' +
        '<div style="background:#f5f5f5;padding:12px;border-radius:4px;margin-bottom:16px;white-space:pre-wrap;font-family:monospace;font-size:12px;max-height:200px;overflow:auto;">' + 
        escapeHtml(s.explanation) + '</div>';

    if (s.suggested_content) {
        body += '<p><strong>Suggested Content:</strong></p>' +
            '<div style="background:#e8f5e9;padding:12px;border-radius:4px;margin-bottom:16px;white-space:pre-wrap;font-family:monospace;font-size:12px;max-height:200px;overflow:auto;border-left:3px solid #4caf50;">' + 
            escapeHtml(s.suggested_content.substring(0, 500)) + (s.suggested_content.length > 500 ? '...' : '') + '</div>';
    }

    body += '</div>';

    var nav = '';
    if (total > 1) {
        nav = '<div style="padding:8px 16px;border-top:1px solid #ddd;display:flex;justify-content:center;gap:8px;">' +
            '<button onclick="pulseboxPrev()" style="padding:4px 12px;cursor:pointer;"' + (idx === 0 ? ' disabled' : '') + '>← Prev</button>' +
            '<button onclick="pulseboxNext()" style="padding:4px 12px;cursor:pointer;"' + (idx === total - 1 ? ' disabled' : '') + '>Next →</button>' +
            '</div>';
    }

    var footer = '<div style="padding:16px;border-top:1px solid #ddd;display:flex;justify-content:flex-end;gap:8px;">' +
        '<button onclick="pulseboxReject(\'' + s.sys_id + '\')" style="padding:8px 16px;background:#dc3545;color:white;border:none;border-radius:4px;cursor:pointer;">Reject</button>' +
        '<button onclick="pulseboxAccept(\'' + s.sys_id + '\')" style="padding:8px 16px;background:#28a745;color:white;border:none;border-radius:4px;cursor:pointer;">Accept & Apply</button>' +
        '</div>';

    modal.innerHTML = header + body + nav + footer;
    overlay.appendChild(modal);
    document.body.appendChild(overlay);

    overlay.onclick = function(e) { if (e.target === overlay) closePulseBoxModal(); };
}

function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function closePulseBoxModal() {
    var overlay = document.getElementById('pulsebox-modal-overlay');
    if (overlay) overlay.remove();
}

function pulseboxPrev() {
    if (window.g_pulseboxIndex > 0) {
        window.g_pulseboxIndex--;
        showPulseBoxModal();
    }
}

function pulseboxNext() {
    if (window.g_pulseboxIndex < window.g_pulseboxSuggestions.length - 1) {
        window.g_pulseboxIndex++;
        showPulseBoxModal();
    }
}

function pulseboxAccept(sysId) {
    var suggestions = window.g_pulseboxSuggestions;
    var s = suggestions.find(function(x) { return x.sys_id === sysId; });
    if (!s) return;

    // Update button to show loading
    var buttons = document.querySelectorAll('#pulsebox-modal-overlay button');
    buttons.forEach(function(b) { b.disabled = true; });
    var acceptBtn = buttons[buttons.length - 1];
    acceptBtn.textContent = 'Applying...';

    // Create merge inference
    var ga = new GlideAjax('PulseBoxAIAB');
    ga.addParam('sysparm_name', 'createMergeInference');
    ga.addParam('sysparm_suggestion_id', sysId);
    ga.getXMLAnswer(function(answer) {
        try {
            var result = JSON.parse(answer);
            if (result.error) {
                alert('Error: ' + result.error);
                closePulseBoxModal();
                return;
            }
            // Poll for completion
            pollMergeStatus(result.inference_id, sysId, s.field_name);
        } catch (e) {
            alert('Error creating merge: ' + e);
            closePulseBoxModal();
        }
    });
}

function pollMergeStatus(inferenceId, suggestionId, fieldName) {
    var ga = new GlideAjax('PulseBoxAIAB');
    ga.addParam('sysparm_name', 'checkMergeStatus');
    ga.addParam('sysparm_inference_id', inferenceId);
    ga.getXMLAnswer(function(answer) {
        try {
            var result = JSON.parse(answer);
            if (result.error) {
                alert('Error: ' + result.error);
                closePulseBoxModal();
                return;
            }

            if (result.state === 'finished') {
                // Apply to form using g_form.setValue
                if (typeof g_form !== 'undefined') {
                    g_form.setValue(fieldName, result.result);
                }

                // Mark suggestion as accepted
                markSuggestionAccepted(suggestionId);

                // Remove from local list and update badge
                window.g_pulseboxSuggestions = window.g_pulseboxSuggestions.filter(function(x) { return x.sys_id !== suggestionId; });
                updateBadgeCount();

                closePulseBoxModal();

                // Show next suggestion if any
                if (window.g_pulseboxSuggestions.length > 0) {
                    window.g_pulseboxIndex = Math.min(window.g_pulseboxIndex, window.g_pulseboxSuggestions.length - 1);
                    showPulseBoxModal();
                }
            } else if (result.state === 'cancelled' || result.state === 'error') {
                alert('Merge failed: ' + result.state);
                closePulseBoxModal();
            } else {
                // Still processing, poll again
                setTimeout(function() {
                    pollMergeStatus(inferenceId, suggestionId, fieldName);
                }, 1000);
            }
        } catch (e) {
            alert('Error checking status: ' + e);
            closePulseBoxModal();
        }
    });
}

function markSuggestionAccepted(sysId) {
    var ga = new GlideAjax('PulseBoxAIAB');
    ga.addParam('sysparm_name', 'acceptSuggestion');
    ga.addParam('sysparm_suggestion_id', sysId);
    ga.getXMLAnswer(function(answer) {
        // Fire and forget - just marking status
        console.log('PulseBox: Marked suggestion ' + sysId + ' as accepted');
    });
}

function updateBadgeCount() {
    var badge = document.getElementById('pulsebox-badge');
    var count = window.g_pulseboxSuggestions.length;
    if (count === 0) {
        if (badge) badge.remove();
    } else {
        badge.innerHTML = '<span style="font-size:16px;">🤖</span> ' + count + ' AI suggestion' + (count > 1 ? 's' : '');
    }
}

function pulseboxReject(sysId) {
    var ga = new GlideAjax('PulseBoxAIAB');
    ga.addParam('sysparm_name', 'rejectSuggestion');
    ga.addParam('sysparm_suggestion_id', sysId);
    ga.getXMLAnswer(function(answer) {
        // Remove from local list
        window.g_pulseboxSuggestions = window.g_pulseboxSuggestions.filter(function(x) { return x.sys_id !== sysId; });
        updateBadgeCount();
        closePulseBoxModal();

        // Show next suggestion if any
        if (window.g_pulseboxSuggestions.length > 0) {
            window.g_pulseboxIndex = Math.min(window.g_pulseboxIndex, window.g_pulseboxSuggestions.length - 1);
            showPulseBoxModal();
        }
    });
}
